1	/* Route geometry shared by the simulation, renderer and authoring tools.
2	
3	   A path is an array of control points [x, y, w, lane] in plate design pixels
4	   (841 × 1870):
5	     x, y  foot point of the lane centre (bottom-centre sprite anchor)
6	     w     the racer's on-screen sprite width at that point (depth scale)
7	     lane  horizontal distance in plate pixels between adjacent lanes (0 = single file)
8	
9	   Positions are smoothed with a Catmull-Rom spline. The path parameter f (0..1)
10	   is proportional to distance measured in racer widths (∫ |dp| / w), so a racer
11	   moving at a constant world speed covers equal f per second whether the path is
12	   near the camera or far away. Fractions in plate data always use this metric. */
13	(function (WW) {
14	  'use strict';
15	  const SUB = 12;
16	  const cache = new WeakMap();
17	
18	  function catmull(p0, p1, p2, p3, t) {
19	    const t2 = t * t, t3 = t2 * t;
20	    return 0.5 * ((2 * p1) + (-p0 + p2) * t + (2 * p0 - 5 * p1 + 4 * p2 - p3) * t2 + (-p0 + 3 * p1 - 3 * p2 + p3) * t3);
21	  }
22	
23	  function prepare(points) {
24	    let prepared = cache.get(points);
25	    if (prepared) return prepared;
26	    if (!points || points.length < 2) throw new Error('A path needs at least two points');
27	    const n = points.length, dense = [];
28	    const at = function (i) { return points[Math.max(0, Math.min(n - 1, i))]; };
29	    for (let i = 0; i < n - 1; i++) {
30	      const p0 = at(i - 1), p1 = at(i), p2 = at(i + 1), p3 = at(i + 2);
31	      for (let k = 0; k < SUB; k++) {
32	        const t = k / SUB;
33	        dense.push([
34	          catmull(p0[0], p1[0], p2[0], p3[0], t),
35	          catmull(p0[1], p1[1], p2[1], p3[1], t),
36	          p1[2] + (p2[2] - p1[2]) * t,
37	          (p1[3] || 0) + ((p2[3] || 0) - (p1[3] || 0)) * t
38	        ]);
39	      }
40	    }
41	    const last = points[n - 1];
42	    dense.push([last[0], last[1], last[2], last[3] || 0]);
43	    const cum = [0];
44	    for (let i = 1; i < dense.length; i++) {
45	      const a = dense[i - 1], b = dense[i];
46	      const len = Math.hypot(b[0] - a[0], b[1] - a[1]) / Math.max(1, (a[2] + b[2]) / 2);
47	      cum.push(cum[i - 1] + len);
48	    }
49	    const total = cum[cum.length - 1] || 1;
50	    prepared = { dense: dense, cum: cum.map(function (c) { return c / total; }), widths: total };
51	    cache.set(points, prepared);
52	    return prepared;
53	  }
54	
55	  /* Returns {x, y, w, lane, tx, ty, f}; (tx, ty) is the unit direction of travel. */
56	  function sample(points, f) {
57	    const p = prepare(points);
58	    f = f < 0 ? 0 : f > 1 ? 1 : f;
59	    const cum = p.cum, d = p.dense;
60	    let lo = 0, hi = cum.length - 1;
61	    while (hi - lo > 1) {
62	      const mid = (lo + hi) >> 1;
63	      if (cum[mid] <= f) lo = mid; else hi = mid;
64	    }
65	    const span = cum[hi] - cum[lo] || 1;
66	    const t = (f - cum[lo]) / span;
67	    const a = d[lo], b = d[hi];
68	    let tx = b[0] - a[0], ty = b[1] - a[1];
69	    const len = Math.hypot(tx, ty) || 1;
70	    return {
71	      x: a[0] + (b[0] - a[0]) * t,
72	      y: a[1] + (b[1] - a[1]) * t,
73	      w: a[2] + (b[2] - a[2]) * t,
74	      lane: a[3] + (b[3] - a[3]) * t,
75	      tx: tx / len, ty: ty / len, f: f
76	    };
77	  }
78	
79	  /* Path fraction of the point on the path closest to (x, y). */
80	  function project(points, x, y) {
81	    const p = prepare(points);
82	    let best = 0, bestD = Infinity;
83	    for (let i = 0; i < p.dense.length; i++) {
84	      const q = p.dense[i];
85	      const d = (q[0] - x) * (q[0] - x) + (q[1] - y) * (q[1] - y);
86	      if (d < bestD) { bestD = d; best = i; }
87	    }
88	    return p.cum[best];
89	  }
90	
91	  /* Foot point for a racer at fraction f, lane value laneX (-1..1, continuous)
92	     and jump height fraction jumpH (0..1). Lanes offset horizontally. */
93	  function racerPoint(points, f, laneX, jumpH) {
94	    const s = sample(points, f);
95	    return {
96	      x: s.x + (laneX || 0) * s.lane,
97	      y: s.y - (jumpH || 0) * s.w * 0.42,
98	      groundY: s.y,
99	      w: s.w, tx: s.tx, ty: s.ty, f: s.f
100	    };
101	  }
102	
103	  /* Length of the path in racer widths; useful when choosing segment lengths. */
104	  function widths(points) { return prepare(points).widths; }
105	
106	  WW.path = { prepare: prepare, sample: sample, project: project, racerPoint: racerPoint, widths: widths };
107	})(globalThis.WW = globalThis.WW || {});
